export const M2_DAY12: ExpandedDay = {
  day: 12,
  module: 2,
  title: 'Vida Social e Rede de Valor',
  theme: 'Construindo conexões que elevam e sustentam',
  subtopics: [
    {
      id: 'm2d12-s1',
      type: 'psychological_understanding',
      title: 'A Psicologia da Conexão Social',
      objective: 'Entender o papel das relações sociais no bem-estar e na atratividade',
      exercises: [
        { id: 'm2d12-s1-e1', type: 'reflection', title: 'Necessidade de Pertencimento', description: 'Maslow colocou pertencimento como necessidade fundamental. Após término, muitos ficam socialmente isolados. Mapeie: como seu isolamento social está após o término? O que mudou nas suas relações?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s1-e2', type: 'self_analysis', title: 'Tipos de Relações', description: 'Mapeie suas relações em categorias: relações de suporte emocional, relações de desafio e crescimento, relações de prazer e diversão, relações de reciprocidade. Está equilibrado?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d12-s1-e3', type: 'journaling', title: 'O Custo do Isolamento', description: 'Isolamento social tem impacto real na saúde: equivale a fumar 15 cigarros por dia em termos de mortalidade. Você se isolou durante o relacionamento ou depois? Qual é o impacto atual?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s1-e4', type: 'reflection', title: 'Reciprocidade Social', description: 'Relacionamentos saudáveis têm reciprocidade. Você tende a dar mais ou receber mais? O desequilíbrio — em qualquer direção — gera ressentimento ou dependência. O que precisa equilibrar?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s1-e5', type: 'self_analysis', title: 'Qualidade vs. Quantidade', description: 'Dunbar: o cérebro humano consegue manter ~150 conhecidos, 50 amigos, 15 próximos e 5 íntimos. Quantas pessoas você tem em cada categoria? A qualidade importa mais que a quantidade.', durationMinutes: 12, difficulty: 1 },
        { id: 'm2d12-s1-e6', type: 'journaling', title: 'Amizades Negligenciadas', description: 'Liste 3-5 amizades importantes que você negligenciou durante o relacionamento. O que aconteceu com cada uma? Qual pode ser reativada com uma ação simples hoje?', durationMinutes: 10, difficulty: 1 },
        { id: 'm2d12-s1-e7', type: 'reflection', title: 'Vulnerabilidade e Conexão', description: 'Brené Brown: conexão real requer vulnerabilidade. Você se permite ser vulnerável com amigos próximos? Ou mantém uma máscara de "estou bem"? Isso afeta a profundidade das conexões.', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s1-e8', type: 'self_analysis', title: 'Valor que Oferece', description: 'Que valor você oferece nas suas relações? Apoio emocional, humor, conselhos, conexões, recursos, presença? Ser conscientemente valioso para outros fortalece seu senso de valor próprio.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s1-e9', type: 'journaling', title: 'O Ex e o Círculo Social', description: 'Como o término afetou seu círculo social? Amigos em comum, grupos, atividades. Que partes da sua vida social você perdeu junto com o relacionamento? Como pode reconstruí-las?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d12-s1-e10', type: 'reflection', title: 'Conexão vs. Distração', description: 'Há diferença entre conexão genuína (que nutre) e interação social como distração (que evita). Analise: suas interações sociais recentes estavam nutrindo ou apenas distraindo?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s1-e11', type: 'self_analysis', title: 'Redes de Alto Valor', description: 'Quem são as pessoas mais valiosas em seu campo profissional ou de interesse que você poderia conhecer? Não para networking oportunista — para conexão genuína baseada em interesses comuns.', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d12-s1-e12', type: 'journaling', title: 'Amizade Masculina', description: 'Amizades profundas entre homens são raras e poderosas. Você tem amigos com quem pode ser vulnerável? Qual o nível de profundidade de suas amizades masculinas?', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s1-e13', type: 'reflection', title: 'Status Social Natural', description: 'Status social não é hierarquia — é a percepção de competência, confiança e contribuição. Você tem status social natural nos seus grupos? O que o define?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s1-e14', type: 'self_analysis', title: 'Energia Social', description: 'Você é introvertido (energia vem da solidão) ou extrovertido (energia vem das pessoas)? Seu ambiente social atual respeita sua natureza energética?', durationMinutes: 8, difficulty: 1 },
        { id: 'm2d12-s1-e15', type: 'journaling', title: 'Impacto nas Pessoas', description: 'Como as pessoas se sentem depois de interagir com você? Mais energizadas, mais claras, mais motivadas? Ou drenadas? Qual impacto você quer ter conscientemente?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s1-e16', type: 'reflection', title: 'Comunidade e Propósito', description: 'Comunidades baseadas em propósito compartilhado (não apenas diversão) criam vínculos mais profundos. Você faz parte de alguma comunidade com propósito? Como pode encontrar uma?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s1-e17', type: 'self_analysis', title: 'Padrões de Dependência Social', description: 'Você usa pessoas para regular suas emoções? Ligar para amigos quando ansioso, estar sempre cercado para não sentir solidão? Isso é diferente de conexão genuína. Onde está a linha?', durationMinutes: 12, difficulty: 3 },
        { id: 'm2d12-s1-e18', type: 'journaling', title: 'Investimento em Relações', description: 'Relações requerem investimento consistente, não apenas quando você precisa. Que ações regulares você pode fazer para manter relações importantes? Datas de aniversário, check-ins, encontros.', durationMinutes: 10, difficulty: 1 },
        { id: 'm2d12-s1-e19', type: 'reflection', title: 'Solidão Saudável', description: 'Há diferença entre solidão dolorosa (isolamento não-escolhido) e solitude nutritiva (solidão escolhida para recarregar). Você consegue estar bem sozinho? Ou solidão sempre dói?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s1-e20', type: 'commitment', title: 'Mapa de Conexões', description: 'Crie um mapa visual de suas relações mais importantes. Para cada uma, escreva uma ação específica para fortalecer nos próximos 30 dias. Relações não se mantêm sozinhas.', durationMinutes: 15, difficulty: 1 }
      ]
    },
    {
      id: 'm2d12-s2',
      type: 'emotional_control',
      title: 'Regulação Emocional em Contextos Sociais',
      objective: 'Desenvolver equilíbrio emocional que permite presença genuína nas interações',
      exercises: [
        { id: 'm2d12-s2-e1', type: 'emotional_regulation', title: 'Ansiedade Social', description: 'Após término, muitos sentem ansiedade em contextos sociais por medo de perguntas sobre o ex, ou por comparação. Identifique: que situações sociais mais te geram ansiedade agora?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s2-e2', type: 'breathing', title: 'Preparação Pré-Social', description: 'Antes de qualquer evento social: 5 respirações lentas (4 dentro, 6 fora). Isso reduz cortisol e ativa o estado calmo-alerta ideal para conexão genuína. Pratique agora como ensaio.', durationMinutes: 5, difficulty: 1 },
        { id: 'm2d12-s2-e3', type: 'journaling', title: 'Máscara Social', description: 'Que máscara você usa em contextos sociais? "Estou bem, tudo ótimo" quando não está? Isso protege a curto prazo mas impede conexão genuína. Quando é seguro ser real?', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s2-e4', type: 'emotional_regulation', title: 'Comparação Social', description: 'Ver amigos em relacionamentos felizes pode doer. Isso é normal e não precisa ser suprimido. Mas pode ser contextualizado: a felicidade deles não diminui suas possibilidades. Como você regula isso?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s2-e5', type: 'meditation', title: 'Meditação de Abertura', description: 'Por 5 minutos, visualize seu coração se abrindo gradualmente. Imagine que você pode receber conexão genuína dos outros. Muitas pessoas se fecham após um término — esta prática reverte isso.', durationMinutes: 7, difficulty: 2 },
        { id: 'm2d12-s2-e6', type: 'emotional_regulation', title: 'Presença vs. Performance', description: 'Há diferença entre estar presente numa interação e performar para ser bem-visto. Presença é genuína e exige segurança emocional. Performance é ansiosa e esgota. Qual você pratica mais?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s2-e7', type: 'journaling', title: 'Regulação Pós-Social', description: 'Após interações sociais intensas, como você se recupera emocionalmente? Você processa o que aconteceu, ou evita? Criar ritual pós-social (reflexão breve) aumenta aprendizado social.', durationMinutes: 8, difficulty: 1 },
        { id: 'm2d12-s2-e8', type: 'emotional_regulation', title: 'Inveja vs. Admiração', description: 'Inveja quer o bem do outro, não deseja. Admiração usa o bem do outro como inspiração. Quando ver alguém que você admira, pratique: "o que ele tem que quero desenvolver em mim?"', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d12-s2-e9', type: 'physical_exercise', title: 'Exercício Pré-Encontro Social', description: 'Exercício físico 30-60 minutos antes de evento social melhora humor, confiança e presença. Endorfinas e testosterona pós-treino criam o estado ideal para conexão. Experimente na próxima oportunidade.', durationMinutes: 30, difficulty: 2 },
        { id: 'm2d12-s2-e10', type: 'emotional_regulation', title: 'Rejeição Social', description: 'Rejeição social ativa as mesmas regiões cerebrais que dor física. Após término, você pode ficar hipersensível à rejeição social. Como você processa quando se sente excluído ou ignorado?', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s2-e11', type: 'journaling', title: 'Narrativa Social', description: 'Que narrativa você conta sobre si mesmo em contextos sociais? "Sou o cara que passou por um término" ou "Sou alguém que está construindo uma vida incrível"? As duas são verdadeiras — qual você escolhe?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s2-e12', type: 'emotional_regulation', title: 'Reciprocidade Emocional', description: 'Em conversas, equilibre escuta e expressão. Quem só escuta se apaga. Quem só fala não conecta. Pratique dar e receber em proporções iguais. Isso exige consciência emocional.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s2-e13', type: 'breathing', title: 'Âncora de Calma', description: 'Crie uma âncora: toque sutilmente o polegar e o indicador enquanto está num estado calmo e confiante. Repita várias vezes. Depois, use a âncora em momentos de ansiedade social.', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d12-s2-e14', type: 'emotional_regulation', title: 'Humor Natural', description: 'Humor genuíno emerge quando você está relaxado com si mesmo. Se você precisar forçar ser engraçado, está performando. Que situações te deixam naturalmente leve e bem-humorado? Busque mais delas.', durationMinutes: 8, difficulty: 1 },
        { id: 'm2d12-s2-e15', type: 'journaling', title: 'Conflito e Relações', description: 'Você evita conflito em amizades? Conflito manejado bem aprofunda relações — mostra que elas suportam honestidade. Evitar sempre conflito cria relações superficiais. Como você lida com conflito?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s2-e16', type: 'emotional_regulation', title: 'Perguntas Sobre o Ex', description: 'Prepare resposta para quando perguntarem sobre o término. Não elaborada — simples, honesta, sem drama: "Estamos em fases diferentes agora. Estou bem." Isso fecha o assunto com dignidade.', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d12-s2-e17', type: 'meditation', title: 'Meditação de Conexão', description: 'Por 5 minutos, visualize as pessoas que te importam. Sinta gratidão por essas conexões. Amor e conexão são recursos infinitos — não diminuem quando compartilhados.', durationMinutes: 7, difficulty: 1 },
        { id: 'm2d12-s2-e18', type: 'emotional_regulation', title: 'Suporte Sem Fardo', description: 'Você pode pedir apoio sem ser um fardo. "Posso te falar sobre o que estou passando?" é diferente de descarregar emocionalmente sem permissão. Pedir apoio com consciência fortalece relações.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s2-e19', type: 'journaling', title: 'Quando Você Conecta de Verdade', description: 'Lembre de uma conversa recente onde sentiu conexão genuína. O que estava diferente? O que havia naquele contexto ou naquela pessoa? Como replicar essas condições?', durationMinutes: 10, difficulty: 1 },
        { id: 'm2d12-s2-e20', type: 'affirmation', title: 'Declaração Social', description: 'Repita: "Sou alguém que cria conexões genuínas. Minha presença adiciona valor. Sou digno de amizades profundas e relações verdadeiras."', durationMinutes: 3, difficulty: 1 }
      ]
    },
    {
      id: 'm2d12-s3',
      type: 'behavioral_exercises',
      title: 'Ações de Construção Social',
      objective: 'Tomar ações concretas que expandem e aprofundam a rede social',
      exercises: [
        { id: 'm2d12-s3-e1', type: 'behavioral_action', title: 'Mensagem de Reconexão', description: 'Escolha 1 amigo que você não fala há mais de 1 mês. Mande uma mensagem genuína sem mencionar o término: "Lembrei de você por [razão específica]. Como está?" Simples e real.', durationMinutes: 5, difficulty: 1 },
        { id: 'm2d12-s3-e2', type: 'social_behavior', title: 'Encontro Presencial', description: 'Marque um encontro presencial com alguém importante hoje. Café, almoço, caminhada. Interação presencial tem 50× mais impacto na oxitocina que interação digital.', durationMinutes: 60, difficulty: 2 },
        { id: 'm2d12-s3-e3', type: 'behavioral_action', title: 'Iniciativa de Grupo', description: 'Organize algo para um grupo de amigos: churrasco, jogo, saída. Liderança social (organizar, convidar, criar o espaço) é uma forma de expressar valor e solidificar posição no grupo.', durationMinutes: 30, difficulty: 3 },
        { id: 'm2d12-s3-e4', type: 'social_behavior', title: 'Escuta Ativa Profunda', description: 'Em alguma conversa hoje, pratique escuta 100%: sem celular, sem preparar resposta enquanto o outro fala, perguntas de aprofundamento. A maioria nunca experimenta ser realmente ouvida.', durationMinutes: 30, difficulty: 2 },
        { id: 'm2d12-s3-e5', type: 'behavioral_action', title: 'Novo Ambiente Social', description: 'Visite um novo ambiente social que reflete seus interesses: aula de algo, clube, grupo de corrida, evento cultural. Novos ambientes criam novas conexões e quebram o isolamento do término.', durationMinutes: 90, difficulty: 2 },
        { id: 'm2d12-s3-e6', type: 'social_behavior', title: 'Ato de Serviço', description: 'Faça algo genuinamente útil para alguém hoje sem expectativa de retorno. Ajudar uma mudança, emprestar um livro, indicar alguém para trabalho. Generosidade constrói capital social.', durationMinutes: 30, difficulty: 1 },
        { id: 'm2d12-s3-e7', type: 'behavioral_action', title: 'Expansão de Rede Profissional', description: 'Conecte-se com alguém na sua área profissional que admira. Não para pedir favor — para aprender, trocar, contribuir. Networking genuíno é construído em interesse mútuo.', durationMinutes: 20, difficulty: 2 },
        { id: 'm2d12-s3-e8', type: 'social_behavior', title: 'Presença Digital com Intenção', description: 'Se usar redes sociais, publique algo genuíno que reflete quem você está se tornando — não uma exibição, mas uma expressão real. Autenticidade atrai autenticidade.', durationMinutes: 15, difficulty: 2 },
        { id: 'm2d12-s3-e9', type: 'behavioral_action', title: 'Mentoria Informal', description: 'Identifique alguém que você pode ajudar com sua experiência ou conhecimento — mesmo que pequeno. Ensinar consolida aprendizado e cria conexões de alto valor.', durationMinutes: 30, difficulty: 2 },
        { id: 'm2d12-s3-e10', type: 'social_behavior', title: 'Elogio Específico', description: 'Dê um elogio genuíno e específico a alguém hoje. Não genérico — específico: "Admiro como você [ação concreta]." Especificidade mostra que você realmente prestou atenção.', durationMinutes: 5, difficulty: 1 },
        { id: 'm2d12-s3-e11', type: 'behavioral_action', title: 'Comunidade de Interesse', description: 'Junte-se a uma comunidade online ou presencial baseada em um dos seus interesses genuínos. Comunidades de interesse criam conexões naturais sem esforço forçado.', durationMinutes: 30, difficulty: 1 },
        { id: 'm2d12-s3-e12', type: 'social_behavior', title: 'Conversa Sem Agenda', description: 'Tenha uma conversa onde você genuinamente não quer nada da outra pessoa. Apenas conexão. Isso é raro e muito valorizado. Quem consegue se desprender de agenda cria conexões profundas.', durationMinutes: 30, difficulty: 2 },
        { id: 'm2d12-s3-e13', type: 'behavioral_action', title: 'Presença em Evento', description: 'Apareça em um evento onde você sabe que conhecidos estarão. Não para fazer networking agressivo — apenas para estar presente e deixar a vida acontecer naturalmente.', durationMinutes: 120, difficulty: 2 },
        { id: 'm2d12-s3-e14', type: 'social_behavior', title: 'Apresentação de Pessoas', description: 'Conecte duas pessoas do seu círculo que se beneficiariam de se conhecer. Ser um conector social é uma das formas mais valiosas de capital social.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s3-e15', type: 'behavioral_action', title: 'Participação Consistente', description: 'Escolha um grupo ou atividade e comprometa-se a aparecer toda semana por 1 mês. Consistência cria familiaridade e familiaridade cria conexão. Uma aparição não constrói nada.', durationMinutes: 60, difficulty: 2 },
        { id: 'm2d12-s3-e16', type: 'social_behavior', title: 'Curiosidade Genuína', description: 'Em toda conversa, pratique curiosidade genuína: faça perguntas sobre a experiência interna das pessoas, não apenas fatos. "Como você se sentiu com isso?" abre mais conexão que "O que aconteceu?"', durationMinutes: 30, difficulty: 2 },
        { id: 'm2d12-s3-e17', type: 'behavioral_action', title: 'Reconhecimento de Aniversário', description: 'Revise seus contatos e identifique aniversários próximos. Mande mensagens personalizadas (não só no dia — pode ser antes). Atenção ao que importa para outros é capital social genuíno.', durationMinutes: 15, difficulty: 1 },
        { id: 'm2d12-s3-e18', type: 'social_behavior', title: 'Limite Verbal', description: 'Em alguma interação hoje, pratique estabelecer um limite de forma calma e direta: "Hoje não consigo, mas na próxima semana sim" ou "Prefiro não falar sobre isso agora." Limites constroem respeito.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s3-e19', type: 'behavioral_action', title: 'Apoio Real em Crise', description: 'Se souber de alguém passando por dificuldade, ofereça apoio concreto: não "qualquer coisa me chame", mas "posso te levar, ajudar com X, ligar quinta às 7." Especificidade é amor em ação.', durationMinutes: 20, difficulty: 2 },
        { id: 'm2d12-s3-e20', type: 'commitment', title: 'Calendário Social', description: 'Agende agora 3 interações sociais significativas para os próximos 14 dias. Relações que ficam "quando der" nunca acontecem. Coloque na agenda como compromisso inamovível.', durationMinutes: 10, difficulty: 1 }
      ]
    },
    {
      id: 'm2d12-s4',
      type: 'reconquest_actions',
      title: 'Rede Social como Contexto de Reconquista',
      objective: 'Usar o contexto social estrategicamente sem manipulação ou artifício',
      exercises: [
        { id: 'm2d12-s4-e1', type: 'reconquest_strategy', title: 'Visibilidade Natural', description: 'Reconquistas bem-sucedidas geralmente envolvem o ex ver ou ouvir sobre sua vida de forma natural, não forçada. Participar ativamente da vida social cria esse contexto organicamente.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s4-e2', type: 'reconquest_strategy', title: 'Amigos em Comum', description: 'Amigos em comum são pontos de contato naturais. Trate-os com respeito genuíno, não como espiões ou canais de mensagem. Eles perceberão a diferença — e ela também perceberá.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s4-e3', type: 'social_behavior', title: 'Presença sem Desespero', description: 'Em contextos onde ela pode estar: seja o homem que está aproveitando genuinamente, não o que está monitorando o espaço. Presença despreocupada é magneticamente diferente de presença desesperada.', durationMinutes: 30, difficulty: 3 },
        { id: 'm2d12-s4-e4', type: 'reconquest_strategy', title: 'Reputação Social', description: 'O que as pessoas falam sobre você quando você não está presente? Essa é sua reputação real. Alta reputação social — construída por ações, não palavras — chega a ela indiretamente.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s4-e5', type: 'social_behavior', title: 'Não Usar Terceiros', description: 'Nunca use amigos em comum para enviar mensagens indiretas, monitorar ela, ou fazer relatórios. Isso é manipulação e destrói tanto sua reputação quanto a possibilidade de reconquista.', durationMinutes: 5, difficulty: 1 },
        { id: 'm2d12-s4-e6', type: 'reconquest_strategy', title: 'Eventos em Comum', description: 'Se houver eventos onde ambos provavelmente estarão: apareça com a intenção de aproveitar genuinamente. Se houver contato natural, seja caloroso e breve. Não force. Não evite completamente.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s4-e7', type: 'self_analysis', title: 'Status Social vs. Postura Social', description: 'Status social elevado não significa arrogância. Significa conforto e competência. Analise: você tende mais para arrogante ou para inseguro em contextos sociais? Qual o equilíbrio ideal?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s4-e8', type: 'reconquest_strategy', title: 'Não Falar Mal', description: 'Nunca fale mal dela com amigos em comum. Zero. Não importa o que aconteceu. Quem fala mal do ex demonstra baixo caráter. E chega sempre até ela.', durationMinutes: 5, difficulty: 1 },
        { id: 'm2d12-s4-e9', type: 'social_behavior', title: 'Construindo Status', description: 'Status social concreto: ser a pessoa que resolve problemas, que sabe coisas, que conecta pessoas, que lidera quando necessário. Como você pode exercer mais isso no seu círculo atual?', durationMinutes: 20, difficulty: 2 },
        { id: 'm2d12-s4-e10', type: 'reconquest_strategy', title: 'Redes Sociais e o Ex', description: 'Dilema das redes sociais: seguir ou não seguir? Regra geral: se estiver em no-contact, remova o acesso. Se no-contact terminou e quer reconectar, siga, mas não interaja com fotos do passado.', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d12-s4-e11', type: 'self_analysis', title: 'Competição Social', description: 'Você entra em competição quando outros homens são mencionados? Ciúme ativo no contexto pós-término é uma das formas mais rápidas de afastar. Trabalhe a segurança interna antes do contato.', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s4-e12', type: 'reconquest_strategy', title: 'Expansão de Mundo', description: 'Homens que expandem seu mundo — novas experiências, novos lugares, novas conexões — são inerentemente mais interessantes. Sua vida está se expandindo ou se contraindo desde o término?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s4-e13', type: 'social_behavior', title: 'Humor Descompromissado', description: 'Humor leve sobre a situação (não sobre ela) é sinal de saúde. Se consegue rir de si mesmo e da ironia da vida, demonstra segurança emocional que é profundamente atraente.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s4-e14', type: 'reconquest_strategy', title: 'Sobre o Que as Pessoas Falam', description: 'O que você quer que as pessoas falem sobre você quando conversam com ela? Não "ele está sofrendo muito" — mas "ele está incrível, parece diferente, cresceu muito." Essas conversas acontecem naturalmente.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s4-e15', type: 'self_analysis', title: 'O Lugar da Reconquista na Vida', description: 'A reconquista deve ser uma das coisas que você busca — não A ÚNICA. Quando é tudo, você perde o equilíbrio. Quanto espaço mental a reconquista ocupa na sua cabeça hoje (0-100%)?', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s4-e16', type: 'reconquest_strategy', title: 'Preparando o Primeiro Contato', description: 'O primeiro contato não deve ser para reconciliação — deve ser natural, leve, sem agenda aparente. O que seria um primeiro contato natural e contextualmente adequado para sua situação?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d12-s4-e17', type: 'social_behavior', title: 'Presença Genuína', description: 'A maior arma de sedução não é o que você diz — é sua presença. Presença é a qualidade de estar completamente aqui, sem divagar, sem performar. Como você cultiva isso?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s4-e18', type: 'reconquest_strategy', title: 'Timing Emocional', description: 'Tente reconectar quando você está em baixo emocional e vai transmitir desespero. O timing certo é quando você genuinamente está bem — não performando que está bem.', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d12-s4-e19', type: 'self_analysis', title: 'Checagem de Prontidão', description: 'Em uma escala de 1-10, quão preparado você está para um primeiro contato sem desespero, sem agenda, sem ansiedade? O que precisa melhorar antes de estar no nível 8+?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s4-e20', type: 'commitment', title: 'Compromisso Social', description: 'Escreva: "Vou construir minha vida social baseado em valor genuíno, não como estratégia de reconquista. Minha rede social vai crescer porque sou alguém que contribui, não porque preciso de algo."', durationMinutes: 5, difficulty: 1 }
      ]
    },
    {
      id: 'm2d12-s5',
      type: 'structured_reflection',
      title: 'Reflexão: Conexão, Isolamento e Valor Social',
      objective: 'Integrar aprendizados sobre vida social com identidade e crescimento pessoal',
      exercises: [
        { id: 'm2d12-s5-e1', type: 'reflection', title: 'Qual é o Seu Papel Social', description: 'Nos seus grupos, qual papel você naturalmente assume? Mediador, energizador, conselheiro, organizador, desafiador? Esse papel reflete quem você é ou quem você acha que deve ser?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s5-e2', type: 'journaling', title: 'Memória Social Positiva', description: 'Lembre de uma interação social que o deixou cheio de energia e significado. O que havia nela? Que tipo de conexão, que tipo de conversa? Como pode criar mais momentos assim?', durationMinutes: 10, difficulty: 1 },
        { id: 'm2d12-s5-e3', type: 'reflection', title: 'Relações Tóxicas', description: 'Sem drama: identifique 1-2 relações no seu círculo que consistentemente drenam, diminuem, ou te deixam pior. O que você pode fazer — gradualmente — para reduzir essa exposição?', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s5-e4', type: 'self_analysis', title: 'Modelagem de Relacionamentos', description: 'Que modelos de relacionamento você aprendeu na família? Como eles influenciam suas amizades e expectativas sociais? Há padrões que você quer replicar ou evitar?', durationMinutes: 12, difficulty: 3 },
        { id: 'm2d12-s5-e5', type: 'journaling', title: 'Gratidão por Conexões', description: 'Escreva sobre 3 relações pelas quais é genuinamente grato. O que cada uma trouxe para sua vida? Como você pode expressar essa gratidão de forma concreta?', durationMinutes: 10, difficulty: 1 },
        { id: 'm2d12-s5-e6', type: 'reflection', title: 'Quem Você Quer Atrair', description: 'Não romanticamente — que tipo de pessoas você quer ter na sua vida? Defina as qualidades: honestas, ambiciosas, generosas, divertidas, intelectualmente estimulantes. O que você precisa ser para atrair essas pessoas?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s5-e7', type: 'self_analysis', title: 'Contribuição vs. Consumo', description: 'Você contribui mais do que consome nas suas relações? Consumo: sempre pedindo apoio, atenção, recursos. Contribuição: oferecendo valor, apoio, tempo. Qual é o seu padrão atual?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s5-e8', type: 'journaling', title: 'Amizade Ideal', description: 'Descreva a amizade ideal que você quer ter em sua vida. Que tipo de conexão, que tipo de conversas, que nível de profundidade. Isso clarifica onde investir.', durationMinutes: 10, difficulty: 1 },
        { id: 'm2d12-s5-e9', type: 'reflection', title: 'Confiança e Traição', description: 'Você é alguém de fiar? Guarda segredos, cumpre promessas, aparece quando prometeu? Confiabilidade é a base de qualquer relação profunda. Em que áreas você pode melhorar?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s5-e10', type: 'self_analysis', title: 'Status Social e Autoestima', description: 'Sua autoestima flutua com base em aprovação social? Isso cria ansiedade e inconsistência. Autoestima sólida é interna, não dependente de como os outros te veem. Onde você está neste espectro?', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s5-e11', type: 'journaling', title: 'Impacto Que Quer Ter', description: 'Em 5 anos, qual impacto você quer ter nas vidas das pessoas ao seu redor? Não famoso ou público — as pessoas próximas. Como sua presença vai ter mudado algo neles?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d12-s5-e12', type: 'reflection', title: 'Limites e Relações', description: 'Pessoas com limites claros são respeitadas e constroem relações mais saudáveis. Em que situações você não tem limites claros com pessoas próximas? O que custaria estabelecê-los?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s5-e13', type: 'self_analysis', title: 'Herança Social', description: 'Você tende a reproduzir os padrões de relacionamento social da sua família de origem? Mais isolado, mais dependente, mais agitado? O que você quer conscientemente cultivar?', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s5-e14', type: 'journaling', title: 'O Que Você Aprende das Pessoas', description: 'Todo ser humano tem algo para te ensinar. Quem te ensinou algo inesperado recentemente? Que lição você carrega dessa interação?', durationMinutes: 8, difficulty: 1 },
        { id: 'm2d12-s5-e15', type: 'reflection', title: 'Comunidade como Espelho', description: 'A comunidade que você frequenta reflete e reforça sua identidade. Se quer crescer, precisa de comunidade de crescimento. Seu círculo atual te desafia ou te conforta no status quo?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s5-e16', type: 'self_analysis', title: 'Solitude e Conexão', description: 'Equilíbrio: solitude para recarregar e autoconhecer + conexão para crescer e pertencer. Onde você está desequilibrado? Muito isolado ou muito dependente de estar com outros?', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d12-s5-e17', type: 'journaling', title: 'Perdão Social', description: 'Há alguém que você precisa perdoar — um amigo que te decepcionou, que ficou com ela, que desapareceu? Perdão não é absolver — é libertar você mesmo do peso.', durationMinutes: 12, difficulty: 3 },
        { id: 'm2d12-s5-e18', type: 'reflection', title: 'O Que é Real', description: 'Redes sociais mostram highlights. A vida real é diferente. Você tende a se sentir inferior ao ver as vidas "perfeitas" dos outros nas redes? Como criar um relacionamento mais saudável com isso?', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d12-s5-e19', type: 'self_analysis', title: 'Mapeamento de Oportunidades', description: 'Onde estão as pessoas com quem você poderia criar conexões significativas que ainda não estão na sua vida? Identifique ambientes específicos que você poderia começar a frequentar.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s5-e20', type: 'journaling', title: 'Síntese do Dia 12', description: 'Escreva: 3 insights sobre sua vida social. 1 relação que vai investir mais. 1 relação que vai reduzir. 1 novo contexto social que vai explorar. Específico e com prazo.', durationMinutes: 10, difficulty: 1 }
      ]
    },
    {
      id: 'm2d12-s6',
      type: 'mindset_reprogramming',
      title: 'Reprogramação: Abundância Social',
      objective: 'Substituir mentalidade de isolamento e escassez por mentalidade de abundância e contribuição',
      exercises: [
        { id: 'm2d12-s6-e1', type: 'mindset_reprogramming', title: 'Da Escassez para a Abundância', description: 'Mentalidade de escassez social: "não tenho amigos", "ninguém me entende", "fico sozinho". Mentalidade de abundância: "há conexões possíveis em todo lugar", "tenho valor a oferecer". Qual domina em você?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s6-e2', type: 'affirmation', title: 'Afirmação de Valor Social', description: 'Repita: "Sou uma presença positiva na vida das pessoas. Tenho algo genuíno a oferecer. Conexões naturais e profundas são possíveis para mim."', durationMinutes: 3, difficulty: 1 },
        { id: 'm2d12-s6-e3', type: 'mindset_reprogramming', title: 'Necessidade vs. Escolha', description: 'Quando você está com pessoas por necessidade emocional, isso é percebido. Quando está por escolha genuína, também é percebido. Trabalhe para estar com pessoas por escolha, não por carência.', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s6-e4', type: 'visualization', title: 'Cena de Conexão Plena', description: 'Visualize uma cena social onde você está completamente presente, relaxado, genuinamente alegre, contribuindo. Veja a qualidade da sua energia e como as pessoas ao redor respondem. Passe 5 min nesta cena.', durationMinutes: 7, difficulty: 2 },
        { id: 'm2d12-s6-e5', type: 'mindset_reprogramming', title: 'Rejeição como Filtro', description: 'Rejeição social não é fracasso — é filtro. Nem toda conexão é compatível. Rejeição elimina incompatibilidade, não valor. Como você pode ver próximas rejeições como filtro, não julgamento?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s6-e6', type: 'affirmation', title: 'Contribuição Como Identidade', description: 'Repita: "Sou alguém que cria valor onde vai. Não preciso de nada dos outros para ser completo. Contribuo porque é quem sou, não porque preciso de algo em troca."', durationMinutes: 3, difficulty: 1 },
        { id: 'm2d12-s6-e7', type: 'mindset_reprogramming', title: 'Aprovação Interna', description: 'Você precisa de validação externa para sentir que é socialmente adequado? Trabalhe para que sua bússola social seja interna: "Agi de acordo com meus valores? Fui genuíno?" Isso é suficiente.', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s6-e8', type: 'visualization', title: 'Roda Social Plena', description: 'Visualize sua vida social ideal em 1 ano: amigos próximos de qualidade, atividades sociais nutritivas, presença social que você ama. O que é diferente da situação atual? O que pode começar a construir hoje?', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d12-s6-e9', type: 'mindset_reprogramming', title: 'Conexão Sem Expectativa', description: 'A maioria das interações sociais morrem pela expectativa de resultado. "Fui legal, por que não me ligou?" Conexão sem expectativa é mais leve, mais genuína e, paradoxalmente, mais atraente.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s6-e10', type: 'affirmation', title: 'Pertencimento Incondicional', description: 'Repita: "Eu pertenço. Não preciso provar meu valor para ter direito de espaço. Minha presença tem valor inerente, independente de aprovação."', durationMinutes: 3, difficulty: 1 },
        { id: 'm2d12-s6-e11', type: 'mindset_reprogramming', title: 'Energia que Você Traz', description: 'Você controla a energia que entra nos ambientes sociais. Alta energia (genuína, não forçada) é contagiante. Baixa energia drena os outros. Que energia você conscientemente quer trazer?', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d12-s6-e12', type: 'visualization', title: 'Impacto Futuro', description: 'Visualize-se sendo a pessoa que outros buscam não por recursos ou status, mas pela qualidade de sua presença e caráter. Como você chega a ser essa pessoa? Que escolhas diárias te levam lá?', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d12-s6-e13', type: 'mindset_reprogramming', title: 'Solidão como Força', description: 'Pessoas que suportam bem a solidão são mais autênticas socialmente — não precisam de aprovação para sobreviver. Solidão bem habitada cria presença social mais forte. Como você está desenvolvendo isso?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s6-e14', type: 'affirmation', title: 'Comunidade Que Virá', description: 'Repita: "Estou construindo a comunidade que mereço, com pessoas que refletem quem estou me tornando. Isso leva tempo e consistência — e estou comprometido com o processo."', durationMinutes: 3, difficulty: 1 },
        { id: 'm2d12-s6-e15', type: 'mindset_reprogramming', title: 'Cada Interação Importa', description: 'Toda interação — com o caixa do mercado, com um colega de trabalho, com o Uber — é prática de presença e caráter. Quem você é nas pequenas interações é quem você realmente é.', durationMinutes: 8, difficulty: 1 },
        { id: 'm2d12-s6-e16', type: 'visualization', title: 'O Homem Social Pleno', description: 'Visualize você como alguém que navega contextos sociais com facilidade, autenticidade e propósito. Não perfeito — mas completamente em paz com quem é, independente de onde está.', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d12-s6-e17', type: 'mindset_reprogramming', title: 'Amor Sem Condição de Retorno', description: 'Amar amigos, familiares e até a ex sem condicionar esse amor a retorno é a expressão mais elevada de força emocional. Isso não é ingenuidade — é escolha consciente de quem você quer ser.', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d12-s6-e18', type: 'affirmation', title: 'Generosidade Social', description: 'Repita: "Sou generoso com minha presença, meu tempo e minha atenção. Essa generosidade não me diminui — ela me define. Abundância se multiplica quando compartilhada."', durationMinutes: 3, difficulty: 1 },
        { id: 'm2d12-s6-e19', type: 'mindset_reprogramming', title: 'O Paradoxo da Popularidade', description: 'Quem tenta ser popular raramente o é. Quem genuinamente foca no bem dos outros se torna naturalmente atraente socialmente. Como você pode soltar a busca por aprovação e focar em contribuição?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d12-s6-e20', type: 'commitment', title: 'Declaração de Vida Social', description: 'Escreva e assine: "Comprometo-me a construir uma vida social baseada em valor genuíno, presença autêntica e contribuição real. Não por estratégia — por caráter."', durationMinutes: 5, difficulty: 1 }
      ]
    }
  ]
}

export const M2_DAY13: ExpandedDay = {
  day: 13,
  module: 2,
  title: 'Finanças, Propósito e Direção',
  theme: 'Construindo a estrutura material e vocacional da sua vida',
  subtopics: [
    {
      id: 'm2d13-s1',
      type: 'psychological_understanding',
      title: 'Dinheiro, Poder e Autoestima',
      objective: 'Entender a relação entre finanças, autoestima e atratividade',
      exercises: [
        { id: 'm2d13-s1-e1', type: 'reflection', title: 'Dinheiro e Valor Próprio', description: 'Muitos homens associam valor próprio com renda ou patrimônio. Quando a situação financeira é instável, a autoestima cai. Como sua situação financeira atual está afetando sua autoestima?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s1-e2', type: 'self_analysis', title: 'Crenças sobre Dinheiro', description: 'Quais crenças você herdou sobre dinheiro? "Dinheiro é raiz de todo mal", "ricos são desonestos", "não sou bom com dinheiro". Essas crenças moldam comportamento financeiro de forma inconsciente.', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s1-e3', type: 'journaling', title: 'Relação Emocional com Dinheiro', description: 'Como você se sente quando: tem dinheiro? Quando não tem? Quando gasta? Quando economiza? Emoções moldam comportamento financeiro mais do que planilhas. Mapeie suas emoções sobre dinheiro.', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s1-e4', type: 'reflection', title: 'Estabilidade Financeira como Segurança', description: 'Instabilidade financeira cria estresse crônico que sabota relacionamentos, humor e decisões. Não precisa de riqueza — precisa de estabilidade. Qual é a diferença entre os dois para você?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s1-e5', type: 'self_analysis', title: 'Padrões de Gastos', description: 'Observe seus gastos do último mês. Onde o dinheiro foi? Que porcentagem foi para necessidades, investimentos em si mesmo, prazer saudável, e gastos que você se arrepende?', durationMinutes: 15, difficulty: 2 },
        { id: 'm2d13-s1-e6', type: 'journaling', title: 'O Que Dinheiro Representa', description: 'Para você, dinheiro representa: segurança? Liberdade? Status? Poder? Amor? (Gastar em outros como forma de ser amado.) Entender o que representa para você explica muitos comportamentos.', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d13-s1-e7', type: 'reflection', title: 'Propósito e Renda', description: 'As pessoas mais satisfeitas financeiramente geralmente trabalham em algo que as motiva. Há alinhamento entre o que você faz para ganhar dinheiro e o que te dá significado?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s1-e8', type: 'self_analysis', title: 'Renda e Relacionamentos', description: 'Como sua situação financeira afetou seu relacionamento passado? Havia pressão, desequilíbrio, ou uso do dinheiro para compensar outras carências? O que você aprendeu sobre isso?', durationMinutes: 12, difficulty: 3 },
        { id: 'm2d13-s1-e9', type: 'journaling', title: 'Ambição Financeira Honesta', description: 'Quanto você quer ganhar? Por quê? Qual estilo de vida quer ter? Ambição financeira claramente definida é diferente de ganância — é clareza que gera ação direcionada.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s1-e10', type: 'reflection', title: 'Segurança vs. Risco Calculado', description: 'Crescimento financeiro geralmente exige risco calculado. Você tende para excesso de segurança (nunca investe) ou excesso de risco (aposta sem base)? Qual o ponto de equilíbrio ideal?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s1-e11', type: 'self_analysis', title: 'Competências e Renda', description: 'Suas competências atuais justificam sua renda desejada? Que habilidades específicas, se desenvolvidas, poderiam aumentar seu valor de mercado nos próximos 12 meses?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s1-e12', type: 'journaling', title: 'Liberdade Financeira', description: 'O que liberdade financeira significa para você? Não depender do emprego? Ter reserva? Trabalhar só no que ama? Definir com clareza é o primeiro passo para construir.', durationMinutes: 10, difficulty: 1 },
        { id: 'm2d13-s1-e13', type: 'reflection', title: 'Presente vs. Futuro Financeiro', description: 'Você tende a sacrificar prazer presente para construir futuro (excesso de frugalidade) ou sacrificar futuro para prazer presente (excesso de gastos)? Onde está o equilíbrio saudável?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s1-e14', type: 'self_analysis', title: 'O Custo do Término', description: 'Não romanticamente — literalmente: o término gerou algum impacto financeiro? Mudanças de moradia, gastos compartilhados, planos que mudaram? Como você está gerenciando isso?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s1-e15', type: 'journaling', title: 'Mentoria Financeira', description: 'Quem você admira financeiramente? O que essa pessoa faz diferente? Que livro, curso ou mentor poderia ajudar a elevar seu entendimento financeiro?', durationMinutes: 10, difficulty: 1 },
        { id: 'm2d13-s1-e16', type: 'reflection', title: 'Dinheiro e Masculinidade', description: 'Há pressão cultural para que homens sejam os provedores. Como essa pressão afeta sua relação com dinheiro? É saudável ou cria ansiedade desnecessária?', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d13-s1-e17', type: 'self_analysis', title: 'Ativos vs. Passivos', description: 'Ativo: gera dinheiro. Passivo: consome dinheiro. Suas decisões financeiras recentes estão criando ativos ou acumulando passivos? Um inventário honesto sem auto-julgamento.', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s1-e18', type: 'journaling', title: 'O Que Você Construiria', description: 'Se dinheiro não fosse limitante, o que você construiria? Empresa? Projetos? Impacto? Às vezes essa resposta revela propósito que pode ser perseguido com os recursos que você já tem.', durationMinutes: 12, difficulty: 1 },
        { id: 'm2d13-s1-e19', type: 'reflection', title: 'Suficiência', description: 'Quanto é suficiente? Pesquisas mostram que felicidade aumenta com renda até certo ponto, depois estabiliza. Você sabe qual é seu "suficiente"? Ou está numa corrida sem meta?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s1-e20', type: 'commitment', title: 'Uma Ação Financeira Hoje', description: 'Escolha uma ação financeira que você pode tomar hoje: criar orçamento, cancelar gasto desnecessário, pesquisar investimento, pagar uma dívida, ou estudar finanças por 30 minutos. Faça hoje.', durationMinutes: 30, difficulty: 2 }
      ]
    },
    {
      id: 'm2d13-s2',
      type: 'emotional_control',
      title: 'Regulando o Estresse Financeiro',
      objective: 'Desenvolver equilíbrio emocional em relação a desafios materiais',
      exercises: [
        { id: 'm2d13-s2-e1', type: 'emotional_regulation', title: 'Ansiedade Financeira', description: 'Estresse financeiro é um dos mais prevalentes e menos discutidos. Você sente ansiedade ao pensar em dinheiro? Como isso se manifesta no corpo? No comportamento?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s2-e2', type: 'breathing', title: 'Respiração para Clareza Financeira', description: 'Quando precisar tomar decisão financeira importante: 5 minutos de respiração lenta antes. Decisões financeiras tomadas em estado de ansiedade são sistematicamente piores. Calibre o estado primeiro.', durationMinutes: 6, difficulty: 1 },
        { id: 'm2d13-s2-e3', type: 'journaling', title: 'Medos Financeiros', description: 'Escreva seus maiores medos financeiros. Depois escreva: "Qual é o pior cenário real? O que eu faria se esse cenário acontecesse?" Especificidade elimina o poder do medo vago.', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s2-e4', type: 'emotional_regulation', title: 'Identidade e Renda', description: 'Se você perdesse sua renda amanhã, quem seria? Sua identidade não pode ser sua renda. Pessoas que constroem identidade em trabalho e dinheiro colapsam quando esses mudam.', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d13-s2-e5', type: 'meditation', title: 'Gratidão Material', description: 'Passe 5 minutos em gratidão genuína pelo que já tem: moradia, alimentação, saúde, conexões. Isso não é negação da ambição — é o piso de estabilidade emocional de onde a ambição cresce.', durationMinutes: 7, difficulty: 1 },
        { id: 'm2d13-s2-e6', type: 'emotional_regulation', title: 'Vergonha Financeira', description: 'Dívidas, renda baixa, erros financeiros — muitos carregam vergonha sobre isso que sabota ação corretiva. Reconheça sem vergonha: onde está sua situação real? Clareza é o primeiro passo.', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d13-s2-e7', type: 'journaling', title: 'Comparação de Riqueza', description: 'Ver outros com mais dinheiro pode gerar inveja ou inspiração. Analise: quando você vê alguém mais rico, o que sente? O que essa reação revela sobre suas crenças sobre dinheiro e mérito?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s2-e8', type: 'emotional_regulation', title: 'Urgência vs. Impulsividade', description: 'Urgência financeira real exige ação. Impulsividade financeira disfarçada de urgência cria problemas. Como você distingue as duas? Que pausa você pode criar antes de decisões financeiras importantes?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s2-e9', type: 'physical_exercise', title: 'Movimento contra Estresse Financeiro', description: 'Quando sentir ansiedade financeira pesada, faça 15 minutos de exercício intenso antes de qualquer coisa. O exercício resetea o estado emocional e melhora a capacidade de raciocínio estratégico.', durationMinutes: 15, difficulty: 2 },
        { id: 'm2d13-s2-e10', type: 'emotional_regulation', title: 'Controle do Controlável', description: 'Em finanças: você não controla a economia, o mercado ou as oportunidades que aparecem. Controla seus gastos, seus investimentos em si mesmo, e suas habilidades. Foque no segundo grupo.', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d13-s2-e11', type: 'journaling', title: 'Passado Financeiro', description: 'Escreva sobre o maior erro financeiro que cometeu. Não para se punir — para extrair a lição. Que decisão diferente tomaria? O que aprendeu sobre si mesmo?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s2-e12', type: 'emotional_regulation', title: 'Humildade Financeira', description: 'Muitos evitam olhar para suas finanças por vergonha ou medo do que vão ver. Humildade financeira é olhar com clareza sem julgamento excessivo. Isso libera a ação corretiva.', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d13-s2-e13', type: 'breathing', title: 'Reset Financeiro', description: 'Após fazer qualquer análise financeira difícil: feche os olhos, 5 respirações lentas. Diga: "Vejo minha situação com clareza. Não com julgamento. Posso agir a partir daqui." Isso cria piso de ação.', durationMinutes: 5, difficulty: 1 },
        { id: 'm2d13-s2-e14', type: 'emotional_regulation', title: 'Paciência com Crescimento', description: 'Crescimento financeiro é composto — lento no início, acelerado depois. A impaciência leva a decisões ruins (apostas, riscos excessivos). Como você cultiva paciência com seu processo financeiro?', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d13-s2-e15', type: 'journaling', title: 'O Que o Dinheiro Não Resolve', description: 'Liste 5 coisas que dinheiro não resolve. Isso não é desvalorizar dinheiro — é criar perspectiva. As coisas mais valiosas da vida raramente têm preço.', durationMinutes: 8, difficulty: 1 },
        { id: 'm2d13-s2-e16', type: 'emotional_regulation', title: 'Generosidade e Abundância', description: 'Paradoxo: dar dinheiro com genuína generosidade (não para impressionar) cria mentalidade de abundância. Escassez é mental antes de ser financeira. Pequeno ato de generosidade hoje.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s2-e17', type: 'meditation', title: 'Visualização de Estabilidade', description: 'Por 7 minutos, visualize-se com estabilidade financeira: não rico — estável. Você tem o suficiente, não deve para ninguém, tem reserva. Como você se sente nesse estado? O que se torna possível?', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d13-s2-e18', type: 'emotional_regulation', title: 'Dívida e Vergonha', description: 'Dívida é uma situação matemática, não um julgamento moral. Muitas pessoas evitam lidar com dívidas porque a vergonha paralisa. Separar a situação do julgamento moral libera a ação.', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d13-s2-e19', type: 'journaling', title: 'Progresso Financeiro', description: 'Reconheça qualquer progresso financeiro que fez — por menor que seja. Economizou algo? Pagou uma conta? Aprendeu algo? O reconhecimento de pequenos progressos mantém a motivação.', durationMinutes: 8, difficulty: 1 },
        { id: 'm2d13-s2-e20', type: 'affirmation', title: 'Afirmação Financeira', description: 'Repita: "Tenho a capacidade de construir estabilidade financeira. Faço escolhas conscientes com dinheiro. Minha situação financeira melhora a cada decisão alinhada com meus valores."', durationMinutes: 3, difficulty: 1 }
      ]
    },
    {
      id: 'm2d13-s3',
      type: 'behavioral_exercises',
      title: 'Ações de Construção Financeira e Vocacional',
      objective: 'Implementar ações concretas que constroem base material e propósito',
      exercises: [
        { id: 'm2d13-s3-e1', type: 'behavioral_action', title: 'Diagnóstico Financeiro', description: 'Hoje: abra suas contas, cartões e aplicativos financeiros. Liste: renda mensal líquida, gastos mensais totais, dívidas com juros, e reserva atual. Números reais, sem arredondar para cima.', durationMinutes: 30, difficulty: 2 },
        { id: 'm2d13-s3-e2', type: 'behavioral_action', title: 'Orçamento Mensal', description: 'Crie um orçamento básico para o próximo mês: distribua a renda em necessidades (50%), investimentos/poupança (20%) e estilo de vida (30%). Simples e executável é melhor que complexo e abandonado.', durationMinutes: 30, difficulty: 2 },
        { id: 'm2d13-s3-e3', type: 'behavioral_action', title: 'Corte de Gasto Inútil', description: 'Identifique 1 gasto recorrente que não agrega valor real: assinatura não usada, serviço esquecido. Cancele hoje. Pequena vitória, sinal importante para você mesmo de que está tomando controle.', durationMinutes: 15, difficulty: 1 },
        { id: 'm2d13-s3-e4', type: 'behavioral_action', title: 'Habilidade Monetizável', description: 'Que habilidade você tem que poderia gerar renda extra — mesmo que pequena? Freelance, aula, consulta, produto digital? Identifique 1 possibilidade e pesquise como começar.', durationMinutes: 30, difficulty: 2 },
        { id: 'm2d13-s3-e5', type: 'behavioral_action', title: 'Investimento em Si', description: 'Invista em seu desenvolvimento hoje: compre um livro relevante, assine um curso, pague uma sessão com mentor. Você é seu melhor ativo. Investir em si tem o maior retorno possível.', durationMinutes: 30, difficulty: 1 },
        { id: 'm2d13-s3-e6', type: 'behavioral_action', title: 'Conversa Difícil Financeira', description: 'Se há uma conversa financeira que você evita (dívida com alguém, renegociação, aumento), faça hoje ou agende para os próximos 3 dias. O custo de evitar sempre supera o custo de enfrentar.', durationMinutes: 30, difficulty: 3 },
        { id: 'm2d13-s3-e7', type: 'behavioral_action', title: 'Pesquisa de Mercado', description: 'Passe 30 minutos pesquisando oportunidades no seu campo: salários praticados, empresas que contratam, habilidades mais valorizadas. Clareza sobre o mercado informa decisões de carreira.', durationMinutes: 30, difficulty: 1 },
        { id: 'm2d13-s3-e8', type: 'behavioral_action', title: 'Rede Profissional', description: 'Entre em contato com alguém na sua área para conversa profissional: trocar experiências, aprender sobre oportunidades, discutir tendências. Relacionamentos profissionais criam mais oportunidades que currículos.', durationMinutes: 20, difficulty: 2 },
        { id: 'm2d13-s3-e9', type: 'behavioral_action', title: 'Projeto Paralelo', description: 'Defina um projeto paralelo de baixo risco que pode gerar renda, portfólio, ou habilidade nos próximos 90 dias. Escreva: o projeto, o primeiro passo, e quando vai começar.', durationMinutes: 20, difficulty: 2 },
        { id: 'm2d13-s3-e10', type: 'behavioral_action', title: 'LinkedIn/Portfólio', description: 'Atualize seu LinkedIn ou portfólio profissional. Adicione conquistas recentes, projetos, habilidades. Presença profissional atualizada cria oportunidades passivas.', durationMinutes: 45, difficulty: 1 },
        { id: 'm2d13-s3-e11', type: 'behavioral_action', title: 'Leitura Financeira', description: 'Leia por 30 minutos sobre finanças pessoais: Pai Rico Pai Pobre, A Psicologia Financeira, ou similar. Conhecimento financeiro é habilidade — como qualquer outra, é desenvolvida com exposição.', durationMinutes: 30, difficulty: 1 },
        { id: 'm2d13-s3-e12', type: 'behavioral_action', title: 'Meta SMART Financeira', description: 'Defina 1 meta financeira SMART para os próximos 90 dias: Específica, Mensurável, Atingível, Relevante, Temporal. Ex: "Economizar R$500/mês até 30/06 cancelando assinaturas X e Y."', durationMinutes: 15, difficulty: 2 },
        { id: 'm2d13-s3-e13', type: 'behavioral_action', title: 'Negociação de Valor', description: 'Identifique uma situação onde você pode negociar melhor: salário, contrato, prestação de serviço. Pesquise o valor de mercado e prepare sua argumentação. Não negociar é deixar dinheiro na mesa.', durationMinutes: 30, difficulty: 3 },
        { id: 'm2d13-s3-e14', type: 'behavioral_action', title: 'Rotina de Revisão Financeira', description: 'Defina um momento semanal (ex: domingo 18h, 30 minutos) para revisar finanças: gastos da semana, progresso para metas. Consistência aqui é o que separa estabilidade financeira de caos.', durationMinutes: 30, difficulty: 2 },
        { id: 'm2d13-s3-e15', type: 'behavioral_action', title: 'Eliminando Dívidas de Alto Juro', description: 'Se tem dívidas com juros altos (cartão, cheque especial), liste-as por taxa de juros. Priorize pagar a de maior juro primeiro (método avalanche). Esta semana: pague qualquer valor acima do mínimo.', durationMinutes: 20, difficulty: 2 },
        { id: 'm2d13-s3-e16', type: 'behavioral_action', title: 'Habilidade de Alto Valor', description: 'Pesquise as 3 habilidades mais bem pagas na sua área agora. Escolha 1 que é compatível com seu perfil e interessante. Comece a aprender hoje — mesmo 20 minutos de estudo é início.', durationMinutes: 20, difficulty: 2 },
        { id: 'm2d13-s3-e17', type: 'behavioral_action', title: 'Propósito e Trabalho', description: 'Pesquise empresas, organizações, ou projetos que trabalham com algo que você acha significativo. Mesmo que não vá trabalhar lá agora, saber onde quer chegar orienta as decisões de hoje.', durationMinutes: 30, difficulty: 1 },
        { id: 'm2d13-s3-e18', type: 'behavioral_action', title: 'Reserva de Emergência', description: 'Meta financeira fundamental: reserva de 3-6 meses de gastos. Se não tem, o objetivo mais importante agora é começar a construir. Defina um valor mensal a guardar, por menor que seja.', durationMinutes: 15, difficulty: 2 },
        { id: 'm2d13-s3-e19', type: 'behavioral_action', title: 'Apresentação Profissional', description: 'Invista em apresentação profissional: currículo atualizado, foto profissional, e-mail formal. Pequenos detalhes de apresentação têm impacto desproporcional em oportunidades profissionais.', durationMinutes: 30, difficulty: 1 },
        { id: 'm2d13-s3-e20', type: 'commitment', title: 'Compromisso Financeiro', description: 'Escreva seu compromisso financeiro de 90 dias: meta específica, ações semanais, e a razão emocional. "Estou construindo estabilidade financeira para [razão profunda]. Vou fazer [ação] toda semana."', durationMinutes: 15, difficulty: 2 }
      ]
    },
    {
      id: 'm2d13-s4',
      type: 'reconquest_actions',
      title: 'Propósito e Direção como Atração',
      objective: 'Usar a clareza de propósito como fundação para reconquista genuína',
      exercises: [
        { id: 'm2d13-s4-e1', type: 'reconquest_strategy', title: 'Propósito como Magnetismo', description: 'Homens com propósito claro são profundamente atraentes. Não por dinheiro ou status — pela energia que propósito gera. Você tem um propósito claro agora? O que está construindo?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s4-e2', type: 'reconquest_strategy', title: 'Estabilidade vs. Sucesso', description: 'Estabilidade emocional e financeira básica é mais atraente que sucesso instável. Não precisa ser rico — precisa de direção, estabilidade e confiança de quem sabe para onde vai.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s4-e3', type: 'self_analysis', title: 'O Que Ela Via', description: 'Ela provavelmente via ou sentia a falta de direção em você — antes ou depois do término. Homens sem propósito claro transmitem insegurança. O que mudou na sua direção de vida agora?', durationMinutes: 12, difficulty: 3 },
        { id: 'm2d13-s4-e4', type: 'reconquest_strategy', title: 'Ambição Visível', description: 'Ambição não precisa ser anunciada — é percebida pela energia e foco de alguém. Quando você está genuinamente perseguindo algo, isso muda sua postura, sua conversa, sua presença.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s4-e5', type: 'social_behavior', title: 'Falar Sobre o Futuro', description: 'Em conversas, pratique falar sobre o que está construindo com entusiasmo genuíno — sem exagerar. Pessoas são atraídas por quem tem visão de futuro. "Estou trabalhando em [X] porque quero [Y]."', durationMinutes: 15, difficulty: 2 },
        { id: 'm2d13-s4-e6', type: 'reconquest_strategy', title: 'Missão Maior', description: 'Homens com missão maior que o relacionamento — que servem a algo além de si mesmos — são consistentemente mais atraentes. Qual é sua missão? O que você está construindo para além de reconquistar ela?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s4-e7', type: 'self_analysis', title: 'Provedoria Emocional', description: 'Além de provisão material, há provisão emocional: ser uma presença estabilizadora, alguém em quem ela pode confiar para estar bem. Você é emocionalmente provedor? O que precisa desenvolver?', durationMinutes: 12, difficulty: 3 },
        { id: 'm2d13-s4-e8', type: 'reconquest_strategy', title: 'Responsabilidade como Atração', description: 'Responsabilidade pessoal — assumir as consequências das próprias escolhas sem culpar outros — é profundamente atraente porque é rara. Como você demonstra responsabilidade pessoal na sua vida agora?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s4-e9', type: 'social_behavior', title: 'Trabalho Como Expressão', description: 'Quando você faz algo com excelência e paixão — mesmo trabalho ordinário — isso é percebido. A qualidade com que você executa qualquer tarefa reflete sua identidade.', durationMinutes: 30, difficulty: 2 },
        { id: 'm2d13-s4-e10', type: 'reconquest_strategy', title: 'Independência Emocional', description: 'Independência financeira e emocional são os dois pilares de um homem que não precisa de ninguém — mas que escolhe amar. Essa distinção é a base de um relacionamento saudável.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s4-e11', type: 'self_analysis', title: 'Crescimento Profissional Visível', description: 'Você está crescendo visivelmente na sua carreira ou projeto? Cada conquista profissional que você compartilha (sem exibição) demonstra que sua vida está em movimento para frente.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s4-e12', type: 'reconquest_strategy', title: 'Conversas que Inspiram', description: 'Quando houver contato, conversas sobre o que você está construindo — com entusiasmo genuíno, não exibição — criam muito mais interesse do que conversas sobre o relacionamento passado.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s4-e13', type: 'social_behavior', title: 'Contribuição Tangível', description: 'Crie algo tangível: um projeto, um produto, um resultado visível. Pessoas que criam são naturalmente mais atraentes do que pessoas que apenas consomem.', durationMinutes: 60, difficulty: 2 },
        { id: 'm2d13-s4-e14', type: 'reconquest_strategy', title: 'Sem Exibição Financeira', description: 'Gastar dinheiro para impressionar é sinal de insegurança. Generosidade genuína — de um lugar de suficiência — é diferente. Nunca tente comprar reconexão. Funciona a curto prazo e destrói a longo prazo.', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d13-s4-e15', type: 'self_analysis', title: 'Congruência', description: 'Congruência é quando o que você diz, pensa e faz está alinhado. Pessoas congruentes são percebidas como autênticas e confiáveis. Em quais áreas você não está congruente atualmente?', durationMinutes: 12, difficulty: 3 },
        { id: 'm2d13-s4-e16', type: 'reconquest_strategy', title: 'Plano de 90 Dias', description: 'Defina o que quer construir nos próximos 90 dias: carreira, finanças, saúde, social. Ter um plano claro muda sua energia e postura. Esse plano existe para você — a reconquista é um bônus possível.', durationMinutes: 20, difficulty: 2 },
        { id: 'm2d13-s4-e17', type: 'social_behavior', title: 'Liderança no Trabalho', description: 'Se tem oportunidade, tome iniciativa no trabalho: lidere um projeto, sugira melhoria, seja o que resolve o problema. Liderança profissional é prática de liderança que se transfere para todos os contextos.', durationMinutes: 30, difficulty: 2 },
        { id: 'm2d13-s4-e18', type: 'reconquest_strategy', title: 'Você Não Precisa Dela', description: 'A única condição para uma reconquista genuína: você não pode precisar dela. Você pode querer muito — mas não precisa. Querer vem da força. Precisar vem da fraqueza. Onde você está agora?', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d13-s4-e19', type: 'self_analysis', title: 'Visão de Longo Prazo', description: 'Onde você quer estar em 5 anos? Profissionalmente, financeiramente, relacionalmente, pessoalmente. Clareza sobre o destino orienta as decisões de hoje.', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s4-e20', type: 'commitment', title: 'Declaração de Propósito', description: 'Escreva em 3-5 frases sua declaração de propósito: o que você está construindo, por que importa, e como isso se conecta com quem você é. Releia toda manhã por 30 dias.', durationMinutes: 15, difficulty: 2 }
      ]
    },
    {
      id: 'm2d13-s5',
      type: 'structured_reflection',
      title: 'Reflexão: Alinhamento Vida-Valores-Propósito',
      objective: 'Avaliar o alinhamento entre vida atual e propósito mais profundo',
      exercises: [
        { id: 'm2d13-s5-e1', type: 'reflection', title: 'O Ikigai Pessoal', description: 'Ikigai japonês: a intersecção do que você ama, no que é bom, pelo que é pago, e do que o mundo precisa. Onde está sua intersecção atual? O que cada círculo contém na sua vida?', durationMinutes: 20, difficulty: 2 },
        { id: 'm2d13-s5-e2', type: 'journaling', title: 'Trabalho com Significado', description: 'O trabalho ideal tem três componentes: competência (você é bom nisso), conexão (te conecta com outros) e contribuição (faz diferença). Como seu trabalho atual pontua em cada um?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s5-e3', type: 'reflection', title: 'O Chamado Pessoal', description: 'Você sente que tem um chamado — algo que foi feito para fazer? Mesmo que não saiba exatamente o que é, há sinais: o que você faz que perde noção do tempo? Onde você mais floresce?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s5-e4', type: 'self_analysis', title: 'Obstáculos Internos', description: 'O que te impede de perseguir seu propósito mais profundo? Medo de falhar? Necessidade de aprovação? Conforto do familiar? Identifique o obstáculo interno mais presente.', durationMinutes: 12, difficulty: 3 },
        { id: 'm2d13-s5-e5', type: 'journaling', title: 'Contribuição que Quer Deixar', description: 'O que você quer ter contribuído para o mundo quando olhar para trás aos 80 anos? Não legado grandiose — contribuição genuína, mesmo que pequena. Isso é seu Norte.', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s5-e6', type: 'reflection', title: 'Energia e Propósito', description: 'Quando você está alinhado com seu propósito, a energia é diferente — não cansaço, mas um cansaço satisfatório. Quando você sente isso no trabalho? O que estava fazendo?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s5-e7', type: 'self_analysis', title: 'Zona de Gênio', description: 'Gay Hendricks: zona de excelência vs. zona de gênio. Excelência é o que você faz bem mas não ama. Gênio é o que você faz naturalmente, ama, e cria impacto único. Qual é sua zona de gênio?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s5-e8', type: 'journaling', title: 'O Próximo Nível', description: 'O que seria o próximo nível na sua carreira ou projeto? Não o destino final — apenas o próximo degrau significativo. Como você saberia que chegou lá? O que seria diferente?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s5-e9', type: 'reflection', title: 'Tempo como Recurso', description: 'Você usa seu tempo de acordo com suas prioridades declaradas? Compare: quanto tempo passa com o que diz importar vs. quanto tempo passa em coisas que não importam. O que a comparação revela?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s5-e10', type: 'self_analysis', title: 'Alinhamento Valores-Trabalho', description: 'Seus valores centrais e seu trabalho estão alinhados? Se trabalha por dinheiro em algo que vai contra seus valores, o desconforto interno se manifesta de formas inesperadas. Qual é o nível de alinhamento?', durationMinutes: 12, difficulty: 3 },
        { id: 'm2d13-s5-e11', type: 'journaling', title: 'Projeto de Vida', description: 'Escreva um parágrafo descrevendo seu projeto de vida — não carreira, mas o arco maior: o que você está construindo, por quem, por quê. Isso não precisa ser perfeito. Apenas honesto.', durationMinutes: 15, difficulty: 2 },
        { id: 'm2d13-s5-e12', type: 'reflection', title: 'Coragem Vocacional', description: 'Seguir propósito real frequentemente requer coragem: abandonar segurança, desafiar expectativas, enfrentar fracasso público. Que coragem vocacional sua vida pede de você agora?', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d13-s5-e13', type: 'self_analysis', title: 'Modelo Mental de Sucesso', description: 'Como você define sucesso? Riqueza? Reconhecimento? Impacto? Família? Paz interior? Sua definição de sucesso orienta todas as suas escolhas. Ela é sua ou herdada de outros?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s5-e14', type: 'journaling', title: 'O Momento de Escolha', description: 'Descreva um momento de sua vida em que tomou uma decisão com base em seus valores, mesmo que difícil. O que essa decisão diz sobre quem você é quando está no seu melhor?', durationMinutes: 12, difficulty: 2 },
        { id: 'm2d13-s5-e15', type: 'reflection', title: 'Integração Vida-Trabalho', description: 'Trabalho e vida não são opostos — são expressões do mesmo ser. Como você integra quem é com o que faz? O que seria diferente se você levasse mais de si mesmo para o trabalho?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s5-e16', type: 'self_analysis', title: 'Crescimento e Conforto', description: 'Crescimento acontece no limite do conforto — não além dele (ansiedade) nem dentro dele (estagnação). Em qual direção você precisa se mover agora: mais desafio ou mais estabilidade?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s5-e17', type: 'journaling', title: 'Motivação Intrínseca', description: 'Motivação extrínseca (dinheiro, status) é frágil. Intrínseca (curiosidade, propósito, crescimento) é sustentável. O que motiva você intrinsecamente no que faz? Como alimentar isso?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s5-e18', type: 'reflection', title: 'O Presente como Fundação', description: 'Independente do futuro — a vida que está vivendo agora é a sua vida. Ela tem valor em si mesma, não apenas como preparação para algo maior. O que você pode apreciar nela agora?', durationMinutes: 8, difficulty: 1 },
        { id: 'm2d13-s5-e19', type: 'self_analysis', title: 'Blocos de Propósito', description: 'O que bloqueia você de viver com mais propósito: falta de clareza, falta de coragem, circunstâncias externas, ou hábitos que sabotam? Identifique o bloqueio principal com precisão.', durationMinutes: 12, difficulty: 3 },
        { id: 'm2d13-s5-e20', type: 'journaling', title: 'Síntese do Dia 13', description: 'Escreva: qual foi o insight mais importante sobre propósito hoje? Que uma ação vai tomar nos próximos 7 dias que está alinhada com esse propósito? Específica, concreta, com data.', durationMinutes: 10, difficulty: 1 }
      ]
    },
    {
      id: 'm2d13-s6',
      type: 'mindset_reprogramming',
      title: 'Reprogramação: Mentalidade de Abundância e Propósito',
      objective: 'Instalar crenças que sustentam criação de valor e vida com propósito',
      exercises: [
        { id: 'm2d13-s6-e1', type: 'mindset_reprogramming', title: 'Escassez Financeira vs. Abundância', description: 'Mentalidade de escassez financeira: "nunca vai ter suficiente", "dinheiro é para outros", "sou azarado financeiramente". Identifique qual crença de escassez é mais ativa em você agora.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s6-e2', type: 'affirmation', title: 'Afirmação de Abundância', description: 'Repita: "Sou capaz de criar valor e ser recompensado por isso. Dinheiro é um recurso que flui para quem cria valor. Estou construindo a capacidade de criar cada vez mais."', durationMinutes: 3, difficulty: 1 },
        { id: 'm2d13-s6-e3', type: 'mindset_reprogramming', title: 'Criador vs. Consumidor', description: 'Mentalidade de criador: "Como posso criar valor?" Mentalidade de consumidor: "O que posso conseguir?" Criadores têm abundância crescente. Consumidores dependem de outros. Em qual modo você opera mais?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s6-e4', type: 'visualization', title: 'Vida de Propósito', description: 'Visualize você daqui a 5 anos, vivendo com propósito claro: trabalhando em algo que ama, contribuindo, com estabilidade financeira. Como você se sente? O que é possível a partir desse lugar?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s6-e5', type: 'mindset_reprogramming', title: 'Merecimento e Sucesso', description: 'Você acredita merecer sucesso financeiro e vocacional? Muitas pessoas autossabotam porque inconscientemente acreditam que não merecem. Qual é sua crença mais profunda sobre merecer sucesso?', durationMinutes: 12, difficulty: 3 },
        { id: 'm2d13-s6-e6', type: 'affirmation', title: 'Propósito Declarado', description: 'Repita: "Tenho valor único a oferecer ao mundo. Meu propósito está emergindo. Cada passo na direção certa, por menor que seja, me aproxima de quem fui destinado a ser."', durationMinutes: 3, difficulty: 1 },
        { id: 'm2d13-s6-e7', type: 'mindset_reprogramming', title: 'Paciência com Construção', description: 'Grandes construções levam tempo. Impaciência leva a atalhos que custam caro a longo prazo. Como você pode cultivar paciência genuína com o processo de construir algo significativo?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s6-e8', type: 'visualization', title: 'Você Criando Valor', description: 'Visualize-se entregando algo de alto valor — em seu trabalho, em sua área, para sua comunidade. Sinta o que é criar algo real. Esse sentimento é o combustível que sustenta esforço.', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d13-s6-e9', type: 'mindset_reprogramming', title: 'Risco e Segurança', description: 'A segurança é uma ilusão a longo prazo. A única segurança real é sua capacidade de criar valor. Investir em si mesmo — habilidades, saúde, relacionamentos — é o único investimento verdadeiramente seguro.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s6-e10', type: 'affirmation', title: 'Construtor Incansável', description: 'Repita: "Sou alguém que constrói. Mesmo nos dias difíceis, avanço. Minha disciplina e propósito criam resultados que se acumulam. Estou exatamente onde preciso estar agora."', durationMinutes: 3, difficulty: 1 },
        { id: 'm2d13-s6-e11', type: 'mindset_reprogramming', title: 'Legado sobre Lucro', description: 'Legado — impacto que permanece — é mais sustentável como motivador que lucro. Qual legado você quer deixar? Essa pergunta reorienta as decisões financeiras e vocacionais para um horizonte mais longo.', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s6-e12', type: 'visualization', title: 'Abundância Compartilhada', description: 'Visualize a abundância que você vai criar sendo partilhada: com família, amigos, causas que importam. Abundância que serve outros é infinitamente mais motivante que abundância só para si.', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d13-s6-e13', type: 'mindset_reprogramming', title: 'O Erro Como Mestre', description: 'Cada erro financeiro ou vocacional contém informação valiosa. "Errei nisso e aprendi aquilo." Reframe todo erro passado como dado que te tornou mais capaz. Qual o mais valioso que tem?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s6-e14', type: 'affirmation', title: 'Direção Clara', description: 'Repita: "Sei para onde estou indo. Minha direção é clara e minha motivação é profunda. Cada dia de ação intencional me aproxima da vida que estou construindo."', durationMinutes: 3, difficulty: 1 },
        { id: 'm2d13-s6-e15', type: 'mindset_reprogramming', title: 'Tempo como Aliado', description: 'O tempo é inimigo de quem não age e aliado de quem é consistente. Com consistência, 5 anos de pequenas ações criam resultados que parecem impossíveis hoje. Você está sendo consistente?', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d13-s6-e16', type: 'visualization', title: 'O Homem de Propósito', description: 'Visualize-se como alguém que acorda todo dia com clareza sobre o que está construindo e por quê. Que energia isso cria? Como sua presença, decisões e relações mudam a partir desse lugar?', durationMinutes: 8, difficulty: 2 },
        { id: 'm2d13-s6-e17', type: 'mindset_reprogramming', title: 'Suficiência e Ambição', description: 'Paradoxo: você pode se sentir suficiente agora E ambicionar mais ao mesmo tempo. Suficiência no ser, ambição no fazer. Esse equilíbrio elimina a ansiedade crônica sem matar a motivação.', durationMinutes: 10, difficulty: 3 },
        { id: 'm2d13-s6-e18', type: 'affirmation', title: 'Trabalho como Expressão', description: 'Repita: "O que faço é expressão de quem sou. Faço com excelência não por obrigação, mas porque excelência é meu padrão. Meu trabalho reflete meu caráter."', durationMinutes: 3, difficulty: 1 },
        { id: 'm2d13-s6-e19', type: 'mindset_reprogramming', title: 'Propósito Além do Eu', description: 'Propósito que serve apenas a você tem vida curta. Propósito que serve outros — família, comunidade, geração futura — tem energia inesgotável. Como seu propósito serve algo maior que você?', durationMinutes: 10, difficulty: 2 },
        { id: 'm2d13-s6-e20', type: 'commitment', title: 'Compromisso de Propósito', description: 'Escreva e assine: "Comprometo-me a viver com propósito e construir com intenção. Não vou desperdiçar meu potencial em distração, medo ou inação. Estou aqui para criar algo real."', durationMinutes: 5, difficulty: 1 }
      ]
    }
  ]
}
